// Magma fixtures for Hilbert cusp forms of parallel weight 2 over real
// quadratic fields (engine/hmf/src/definite.rs; tests only): Magma is used
// as a black box. Run from this directory with
//     magma -b magma-up-general.m > magma-up-general.txt
// For each field Q(sqrt d) below (w the generator of the maximal order with
// w^2 = w + (d - 1)/4 or w^2 = d, as in rqf.rs), each level N of norm <= 12
// and each prime P of norm <= 7 dividing N, a line
//     d | x1 y1 ; x2 y2 | dim | p x y | c_0 c_1 ... c_n
// with N generated by x1 + y1 w and x2 + y2 w, dim = dim S_2(N), P = (p,
// x + y w), and c_i the coefficients of the characteristic polynomial of
// HeckeOperator(HilbertCuspForms(F, N), P) (the operator U_P), constant
// term first. Levels of dimension 0 or with no such prime are left out.
SetColumns(0);
R<x> := PolynomialRing(Rationals());
va, vb, vc := GetVersion();
printf "# Magma %o.%o-%o, black box: HilbertCuspForms, Dimension, HeckeOperator, IdealsUpTo\n", va, vb, vc;
elt := func<K, e | [Integers()!c : c in Eltseq(K!e)]>;
for d in [2, 3, 6, 7, 10, 13, 15, 17, 21, 34] do
  if d mod 4 eq 1 then
    K<w> := NumberField(x^2 - x - (d - 1) div 4);
  else
    K<w> := NumberField(x^2 - d);
  end if;
  O := EquationOrder(K);
  assert O eq MaximalOrder(K);
  O := MaximalOrder(K);
  primes := [t[1] : t in Decomposition(O, p), p in [2, 3, 5, 7] | Norm(t[1]) le 7];
  for N in IdealsUpTo(12, K) do
    g := Generators(N);
    g1 := elt(K, g[1]);
    g2 := #g gt 1 select elt(K, g[2]) else [0, 0];
    M := HilbertCuspForms(K, N);
    dim := Dimension(M);
    ps := [P : P in primes | N subset P];
    if dim eq 0 or #ps eq 0 then
      continue;
    end if;
    for P in ps do
      p := Minimum(P);
      gp := [elt(K, e) : e in Generators(P)];
      gp := [e : e in gp | e[2] ne 0];
      e := #gp eq 0 select [p, 0] else gp[1];
      cp := Eltseq(CharacteristicPolynomial(HeckeOperator(M, P)));
      printf "%o | %o %o ; %o %o | %o | %o %o %o | %o\n", d, g1[1], g1[2], g2[1], g2[2], dim, p, e[1], e[2], Join([Sprint(c) : c in cp], " ");
    end for;
  end for;
end for;
quit;
